		function rebaseOpenClawModelRef(modelRef, providerKey) {
		  const slashIndex = modelRef.indexOf("/");
		  return slashIndex === -1 ? `${providerKey}/${modelRef}` : `${providerKey}${modelRef.slice(slashIndex)}`;
		}
		function rebaseOpenClawSuggestedDefaults(defaults3, providerKey) {
		  const key = providerKey.trim();
		  if (!key) return defaults3;
		  return {
		    model: defaults3.model ? {
		      ...defaults3.model,
		      primary: rebaseOpenClawModelRef(defaults3.model.primary, key),
		      fallbacks: defaults3.model.fallbacks?.map(
		        (modelRef) => rebaseOpenClawModelRef(modelRef, key)
		      )
		    } : void 0,
		    modelCatalog: defaults3.modelCatalog ? Object.fromEntries(
		      Object.entries(defaults3.modelCatalog).map(([modelRef, entry]) => [
		        rebaseOpenClawModelRef(modelRef, key),
		        entry
		      ])
		    ) : void 0
		  };
		}
