		function resolvePiThinkingProfile(options) {
		  const binding = piThinkingBindings.find(
		    (candidate) => candidate.catalogKey === options.catalogKey && candidate.api === options.api
		  );
		  if (!binding) return void 0;
		  return {
		    ...getPiThinkingProfile(binding.profileId),
		    ...binding.modelCompat ? { modelCompat: { ...binding.modelCompat } } : {}
		  };
		}
		function isPiThinkingLevelMap(value) {
		  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
		  const allowed = new Set(PI_THINKING_LEVELS);
		  return Object.entries(value).every(
		    ([key, entry]) => allowed.has(key) && (typeof entry === "string" || entry === null)
		  );
		}

